#ifndef INPUT_MANAGER_H
#define INPUT_MANAGER_H

#include "Config.h"

// Semantic button events generated by InputManager
enum ButtonEvent : uint8_t {
  BTN_EVENT_NONE = 0,
  BTN_EVENT_RESET_SHORT_TAP,    // Released < 0.5s without chord
  BTN_EVENT_RESET_HOLD_RATE,    // Released between 1.5s - 3.0s without chord
  BTN_EVENT_RESET_HOLD_SETUP,   // Held >= 3.5s (fires immediately while held)
  BTN_EVENT_PARK_CHORD,         // Reset + Speed Down held for 2s
  BTN_EVENT_SLEW_FWD_HOLD,      // Speed Up held 2s while in STOP_ST
  BTN_EVENT_SLEW_REV_HOLD       // Speed Down held 2s while in STOP_ST (and Reset not held)
};

class InputManager {
public:
  InputManager();

  // Configures button and microswitch pins with internal pull-up resistors.
  void begin();

  // Resets debounce counters and button repeat state.
  void reset();

  // Polls Speed Up / Speed Down buttons with repeat throttling (BUTTON_REPEAT_DELAY_MS)
  // during RUNNING_ST, FAST_FORWARD_ST, RETURN_ST, and SETUP_ST.
  bool pollSpeedButtons();

  // Master event parser for STOP_ST ("rdy"):
  // Generates clean semantic events for tap, rate hold, setup hold, park chord, and slew holds.
  ButtonEvent pollStopStateEvents();

  bool isSpeedUpPressed() const { return speedUpPressed_; }
  bool isSpeedDownPressed() const { return speedDownPressed_; }
  bool areBothSpeedButtonsPressed() const { return speedUpPressed_ && speedDownPressed_; }
  bool isOnlyOneSpeedButtonPressed() const { return speedUpPressed_ != speedDownPressed_; }
  bool isRepeatCooldownActive() const { return repeatCooldownActive_; }

  // Consecutive-sample debounced limit switch checks (active LOW).
  bool checkStartSwitchTriggered();
  bool checkStopSwitchTriggered();

  // Debounced safety checks:
  bool checkBothSwitchesActiveDebounced();
  bool isStartSwitchDebouncedActive();
  bool isStopSwitchDebouncedActive();

  // Raw instantaneous microswitch reads.
  bool isStartSwitchRawActive() const;
  bool isStopSwitchRawActive() const;

  // Resets all switch-related debounce counters on motion state transitions.
  void resetSwitchDebounce() {
    startSwitchCount_    = 0;
    stopSwitchCount_     = 0;
    bothSwitchesCount_   = 0;
    startDebouncedCount_ = 0;
    stopDebouncedCount_  = 0;
  }

  // Raw and debounced Reset button reads (active LOW).
  bool isResetButtonRawActive() const;
  bool isResetButtonDebouncedActive();

  // Latches the debounced Reset button state as held (used when entering a state
  // via a Reset button hold so release debounce applies immediately).
  void latchResetHeld() {
    resetPin_.active            = true;
    resetPin_.transitioning     = false;
    resetPin_.transitionStartMs = 0;
  }

  // Suppresses Reset button events in STOP_ST until the button has been
  // continuously released (HIGH) for BUTTON_DEBOUNCE_MS.
  void suppressNextResetRelease() {
    latchResetHeld();
    ignoreResetUntilRelease_ = true;
    resetWasPressed_         = false;
    setupFiredWhileHeld_     = false;
  }

private:
  struct DebouncedPin {
    bool          active;
    bool          transitioning;
    unsigned long transitionStartMs;
  };

  static bool isActivelyHeld(const DebouncedPin& s) {
    return s.active && !s.transitioning;
  }

  bool updateDebouncedButton(uint8_t pin, DebouncedPin& state, unsigned long now);

  unsigned long lastRepeatMs_;
  bool          repeatCooldownActive_;
  bool          speedSettlePending_;
  unsigned long speedSettleStartMs_;
  bool          speedUpPressed_;
  bool          speedDownPressed_;
  int           startSwitchCount_;
  int           stopSwitchCount_;
  uint8_t       bothSwitchesCount_;
  uint8_t       startDebouncedCount_;
  uint8_t       stopDebouncedCount_;

  DebouncedPin  resetPin_;
  DebouncedPin  speedUpPin_;
  DebouncedPin  speedDownPin_;

  // State tracking for STOP_ST event parser
  unsigned long resetPressStartMs_;
  unsigned long speedUpPressStartMs_;
  unsigned long speedDownPressStartMs_;
  unsigned long parkChordStartMs_;
  bool          resetWasPressed_;
  bool          setupFiredWhileHeld_;
  bool          parkChordTiming_;
  bool          parkFiredWhileHeld_;
  bool          speedUpHoldTiming_;
  bool          speedDownHoldTiming_;
  bool          slewFwdFiredWhileHeld_;
  bool          slewRevFiredWhileHeld_;
  bool          ignoreResetUntilRelease_;
};

extern InputManager inputManager;

#endif // INPUT_MANAGER_H
